checkRuns.command:
cat > src/routes/contact.kay <<'EOF'
--- server
import { s } from 'kay'
import { checkContact } from '../contact'
import ContactForm from '../components/contact-form.kay'

const contactInput = s.Object({
  name: s.String({ maxLength: 200 }),
  email: s.String({ maxLength: 320 }),
  message: s.String({ maxLength: 5000 }),
})

export const send = action(contactInput, (input, ctx) => {
  const errors = checkContact(input)

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return { name: input.name.trim() }
})
---
head
  title Contact
h1 Contact
ContactForm
EOF
cat > src/components/contact-form.kay <<'EOF'
---
import { send } from '../routes/contact.kay'
import { checkContact } from '../contact'
import type { ContactErrors } from '../contact'

const errors = signal<ContactErrors>(send.failed()?.data?.errors ?? {})
const thanked = signal(send.succeeded()?.data.name ?? '')

async function submit(event: SubmitEvent) {
  event.preventDefault()
  const form = event.currentTarget as HTMLFormElement
  const fields = new FormData(form)
  const found = checkContact({
    name: String(fields.get('name') ?? ''),
    email: String(fields.get('email') ?? ''),
    message: String(fields.get('message') ?? ''),
  })

  errors.set(found)
  thanked.set('')

  if (Object.keys(found).length === 0) {
    thanked.set((await send(fields, { refresh: false })).name)
    form.reset()
  }
}
---
if thanked()
  p(role="status") Thanks, {thanked()}! Your message has been sent.
form(action={send} novalidate onSubmit={submit})
  div
    label(for="name") Name
    input#name(type="text" name="name")
    if errors().name
      p.error {errors().name}
  div
    label(for="email") Email
    input#email(type="email" name="email")
    if errors().email
      p.error {errors().email}
  div
    label(for="message") Message
    textarea#message(name="message")
    if errors().message
      p.error {errors().message}
  button(type="submit") Send
EOF
bun run check 2>&1 | tail -40

cat > tests/site.test.ts <<'EOF'
import { expect, it } from 'bun:test'
import { testSite } from 'kay/test'
import { send } from '../src/routes/contact.kay'

const site = await testSite()

it('sends a valid message', async () => {
  expect(await site.call(send, { name: ' Ada ', email: 'ada@example.com', message: 'A message long enough to pass.' })).toEqual({ name: 'Ada' })
})

it('refuses an invalid one', async () => {
  const refused = await site.refusal(send, { name: '', email: '', message: 'short' })
  expect(refused.status).toBe(422)
  expect(refused.data).toEqual({ errors: { name: 'Name is required.', email: 'Email is required.', message: 'Message must be at least 20 characters.' } })
})

it('answers unknown pages with 404', async () => {
  const page = await site.visit('/books/unknown')
  expect(page.status).toBe(404)
  expect(page.find('h1')[0]?.text).toBe('Not found')
})
EOF
